          <div style={{ width: '100%', maxWidth: 380 }}>

            {/* Logo (navy version) for white panel */}
            <div style={{ marginBottom: 24, textAlign: 'center' }}>
              <img src={logoLight} alt="LHM Madagascar" style={{ height: 44, objectFit: 'contain' }} />
            </div>

